#include "h8_first_instructions.h"
#include "h8_memory_fixture.h"
#include "h8_bit_oracle.h"
#include <algorithm>
#include <cstdio>
using Cpu=yamanix::H8FirstInstructions<Host>;
static unsigned failures=0;
static void check(bool ok,const char* why){if(!ok && ++failures<12)std::fprintf(stderr,"%s\n",why);}
static unsigned count(const Host& h,char k){return unsigned(std::count_if(h.trace.begin(),h.trace.end(),[=](auto e){return std::get<0>(e)==k;}));}
static bool modifies(unsigned op){return op<3||op==4||op==5;}
static uint16_t prefix(unsigned op,unsigned addr){return uint16_t((modifies(op)?0x7f00:0x7e00)|(addr&255));}
static std::vector<uint16_t> program(unsigned op,unsigned bit,unsigned seed,uint32_t addr){return {uint16_t(0x0700|seed),prefix(op,addr),uint16_t(codes[op]|(bit<<4))};}
int main(){
 for(unsigned op=0;op<14;++op)for(unsigned v=0;v<256;++v)for(unsigned bit=0;bit<8;++bit)for(unsigned seed=0;seed<256;++seed){const uint32_t addr=0xffff57;Host h;h.program(program(op,bit,seed,addr));h.data[addr&0xffffff]=uint8_t(v);Cpu c(h);c.run(0,modifies(op)?15:13,1000);auto e=oracle(op,v,bit,seed);std::array<uint16_t,16> want{};check(c.snapshot().registers==want && c.snapshot().ccr==e.ccr && h.data[addr&0xffffff]==e.value,"7340032 indirect operand/bit/CCR cases");check(count(h,'R')==1 && count(h,'W')==unsigned(modifies(op)),"One read and correct write count");if(modifies(op)){auto r=std::find_if(h.trace.begin(),h.trace.end(),[](auto e){return std::get<0>(e)=='R';});auto w=std::find_if(h.trace.begin(),h.trace.end(),[](auto e){return std::get<0>(e)=='W';});check(r<w && std::get<0>(*(w-1))=='I',"Read then prefetch then write");}}
 for(unsigned op=0;op<4;++op)for(unsigned addr=0;addr<256;++addr)for(unsigned src=0;src<16;++src)for(unsigned seed=0;seed<16;++seed){std::array<uint16_t,16> want{};std::vector<uint16_t> p;for(unsigned n=0;n<8;++n){uint32_t v=(0x1234567u*(n+1))^(seed*0x11111111u);want[n]=uint16_t(v);want[n+8]=uint16_t(v>>16);p.insert(p.end(),{uint16_t(0x7a00|n),uint16_t(v>>16),uint16_t(v)});}unsigned index=src&8?want[src&7]&255:want[src&7]/256;auto e=oracle(op,addr,index%8,seed);p.push_back(uint16_t(0x0700|seed));p.push_back(prefix(op,addr));p.push_back(uint16_t(0x6000|(op<<8)|(src<<4)));Host h;h.program(p);h.data[0xffff00|addr]=uint8_t(addr);Cpu c(h);c.run(0,op==3?63:65,1000);check(c.snapshot().registers==want && c.snapshot().ccr==e.ccr && h.data[0xffff00|addr]==e.value && count(h,'R')==1 && count(h,'W')==unsigned(op!=3),"262144 absolute address/source lane cases");}
 for(unsigned kind=0;kind<2;++kind)for(unsigned ext=0;ext<65536;++ext){bool valid=kind?((ext&0xff0f)==0x6000||(ext&0xff0f)==0x6100||(ext&0xff0f)==0x6200||(ext&0xff0f)==0x6700||(ext&0xff8f)==0x6780||(ext&0xff8f)==0x7000||(ext&0xff8f)==0x7100||(ext&0xff8f)==0x7200):((ext&0xff0f)==0x6300||(ext&0xff8f)==0x7300||((ext&0xfc0f)==0x7400));Host h;h.program({uint16_t(kind?0x7f00:0x7e00),uint16_t(ext)});Cpu c(h);bool threw=false;try{c.run(0,15,100);}catch(const std::runtime_error&){threw=true;}check(threw!=valid && c.failed()==!valid,"131072 extension encodings");if(!valid)check(count(h,'R')==0 && count(h,'W')==0,"Rejected extension has no data side effects");}
 for(unsigned split=0;split<=30;++split){Host a,b;a.program(program(1,2,0xa5,0xffff57));b.program(program(1,2,0xa5,0xffff57));a.data[0xffff57]=b.data[0xffff57]=4;Cpu x(a),y(b);x.run(0,30,1000);y.run(0,int(split),1000);y.run(split,int(30-split),1000);check(x.snapshot()==y.snapshot() && a.trace==b.trace && a.data==b.data && count(b,'R')==1 && count(b,'W')==1 && b.data[0xffff57]==0,"Every read/prefetch/write suspension split exactly once");}
 for(bool write:{false,true}){Host h;h.program(program(1,2,0,0xffff57));h.data[0xffff57]=4;h.bad_read=!write;h.bad_write=write;Cpu c(h);bool threw=false;try{c.run(0,30,1000);}catch(const std::runtime_error&){threw=true;}check(threw && c.failed(),"Bus failure poisons owner");check(count(h,'W')==unsigned(write) && h.data[0xffff57]==(write?0:4),"Completed mutation retained without replay on failure");}
 for(unsigned seed=0;seed<1000;++seed){std::vector<uint16_t> p{uint16_t(0x0700|(seed&255))};for(unsigned op=0;op<14;++op)p.insert(p.end(),{prefix(op,0x57),uint16_t(codes[op]|0x20)});p.push_back(0x40c6);Host a,b;a.program(p);b.program(p);a.data[0xffff57]=b.data[0xffff57]=uint8_t(seed);Cpu x(a),y(b);x.run(0,512,10000);uint64_t start=0;unsigned r=seed+1;while(start<512){r=r*1664525u+1013904223u;int n=int(1+r%19);if(start+n>512)n=int(512-start);y.run(start,n,1000);start+=n;}check(x.snapshot()==y.snapshot() && a.trace==b.trace && a.data==b.data,"1000 memory bit partition histories");}
 std::printf("H8 absolute bits: 7340032 immediate, 262144 address/lane, 131072 extension, 31 splits, 1000 partitions: %u failures\n",failures);return failures?1:0;
}
